mapper.select:
SELECT r.reservation_id , r.reservation_no , r.fair_id , f.name AS fair_name , f.poster_image_url AS fair_poster_image_url , r.visit_date , fd.entry_start_time , fd.entry_end_time , r.status AS reservation_status , r.reservation_type , r.reservation_amount AS amount , r.reserved_at , r.payment_expires_at , r.canceled_by
, f.reservation_cancel_deadline_hours AS cancel_deadline_hours , f.reservation_change_deadline_hours AS change_deadline_hours , er.first_checked_in_at AS checked_in_at , p.payment_id , p.status AS payment_status , p.method AS payment_method , p.easy_pay_provider AS easy_pay_provider FROM reservations r JOIN fairs f ON f.fair_id = r.fair_id JOIN fair_dates fd ON fd.fair_id = r.fair_id AND fd.operation_date = r.visit_date LEFT JOIN entry_records er ON er.reservation_id = r.reservation_id
LEFT JOIN payment p ON p.reservation_id = r.reservation_id AND p.payment_type = 'RESERVATION_DEPOSIT' WHERE r.reservation_id = #{reservationId} AND r.user_id = #{userId}

SELECT COUNT(*)
  FROM reservations r
 WHERE r.fair_id = #{fairId}
   AND r.visit_date = #{visitDate}
   AND r.status = #{status}

SELECT EXISTS (
    SELECT 1
      FROM fairs
     WHERE fair_id = #{fairId}
)

SELECT EXISTS (
    SELECT 1
      FROM reservations
     WHERE fair_id = #{fairId}
       AND user_id = #{userId}
       AND visit_date = #{visitDate}
       AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'CHECKED_IN')
)

SELECT EXISTS (
    SELECT 1
      FROM fair_admin_assignments
     WHERE fair_id = #{fairId}
       AND admin_user_id = #{adminUserId}
)

mapper.insert:
INSERT INTO reservations (
       reservation_no
     , fair_id
     , user_id
     , visit_date
     , reservation_type
     , status
     , reservation_amount
     , reserver_name
     , reserver_phone
     , reserver_email
     , channel
     , agreed_terms
     , reservation_terms_version
     , reservation_terms_agreed_at
     , agreed_privacy
     , agreed_marketing
     , reserved_at
     , payment_expires_at
     , created_at
     , updated_at
) VALUES (
       #{reservationNo}
     , #{fairId}
     , #{userId}
     , #{visitDate}
     , #{reservationType}
     , #{status}
     , #{reservationAmount}
     , #{reserverName}
     , #{reserverPhone}
     , #{reserverEmail}
     , #{channel}
     , #{agreedTerms}
     , #{reservationTermsVersion}
     , #{reservationTermsAgreedAt}
     , FALSE
     , FALSE
     , #{reservedAt}
     , #{paymentExpiresAt}
     , #{createdAt}
     , #{updatedAt}
)
